# ═══ MODULE: 07_vllm_config.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 07: vLLM Configuration — NVFP4, Mamba-2, MTP, LatentMoE Flags
# Exact flags for Nemotron 3 Ultra 550B on 8-GPU (H100/H200/B200) clusters
# ════════════════════════════════════════════════════════════════════════════

# ─── ENVIRONMENT VARIABLES (set before vLLM launch) ─────────────────────────
vllm_set_env() {
    export VLLM_USE_FLASHINFER_MOE_FP4=1
    export VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS=1
    export VLLM_ALLOW_LONG_MAX_MODEL_LEN=1
    freenemo_log "vLLM env vars set: FLASHINFER_MOE_FP4=1, MEMORY_PROFILER=1, ALLOW_LONG_MAX_MODEL_LEN=1"
}

# ─── vLLM SERVER COMMAND BUILDER ────────────────────────────────────────────
vllm_build_cmd() {
    local model_path="${1:-/models/nvidia/Nemotron-3-Ultra-550B-NVFP4}"
    local tp_size="${2:-8}"
    local max_len="${3:-1048576}"
    local port="${4:-8000}"

    cat <<EOF
vllm serve ${model_path} \\
    --quantization nvfp4 \\
    --tensor-parallel-size ${tp_size} \\
    --max-model-len ${max_len} \\
    --kv-cache-dtype fp8 \\
    --mamba-backend flashinfer \\
    --mamba-cache-dtype float16 \\
    --enable-mamba-cache-stochastic-rounding \\
    --mamba-cache-philox-rounds 5 \\
    --speculative-config.method mtp \\
    --speculative-config.num-speculative-tokens 5 \\
    --reasoning-parser nemotron_v3 \\
    --tool-call-parser qwen3_coder \\
    --disable-log-requests \\
    --port ${port} \\
    --host 0.0.0.0
EOF
}

# ─── HARDWARE REQUIREMENTS CHECK ────────────────────────────────────────────
vllm_check_hardware() {
    freenemo_banner "🔧 vLLM HARDWARE CHECK — Nemotron 3 Ultra NVFP4"
    freenemo_log "Required: 8x H100/H200 (80GB) or 4x B200/GB200 (SXM + NVLink 4.0)"
    freenemo_log "NVFP4 footprint: ~352 GB VRAM (550B @ 4-bit + 15% overhead)"
    freenemo_log "BF16 footprint: ~1,265 GB (requires 16x H100 or 8x B200)"
    freenemo_log "FP8 (W8A8) footprint: ~660 GB (8x H100 or 4x B200)"

    if command -v nvidia-smi >/dev/null 2>&1; then
        local gpu_count=$(nvidia-smi -L | wc -l)
        local vram_per_gpu=$(nvidia-smi --query-gpu=memory.total --format=csv,noheader,nounits | head -1)
        freenemo_log "Detected: ${gpu_count} GPUs, ${vram_per_gpu}MB VRAM each"
        local total_vram=$((gpu_count * vram_per_gpu / 1024))
        freenemo_log "Total VRAM: ~${total_vram} GB"
        if (( total_vram >= 352 )); then
            freenemo_success "VRAM sufficient for NVFP4 deployment"
        else
            freenemo_warn "VRAM may be insufficient for NVFP4 (need 352 GB)"
        fi
    else
        freenemo_warn "nvidia-smi not available, cannot verify hardware"
    fi

    # Check vLLM version
    if python3 -c "import vllm; print(vllm.__version__)" 2>/dev/null | grep -qE '^0\.(2[3-9]|[3-9])'; then
        freenemo_success "vLLM version >= 0.23.0 (cuDNN graph corruption fix)"
    else
        freenemo_warn "vLLM version may be < 0.23.0 — prefix caching instability risk at >200k tokens"
    fi
}

# ─── NUMA PINNING (for GB200/B200) ──────────────────────────────────────────
vllm_numa_pinning() {
    freenemo_log "For GB200/B200: bind vLLM workers to local CPU socket (NUMA pinning)"
    freenemo_log "  numactl --cpunodebind=0 --membind=0 vllm serve ..."
    freenemo_log "  This bypasses NVLink-C2C cross-socket path, gives ~10% throughput gain"
}

# ─── CUDA GRAPH REVALIDATION ────────────────────────────────────────────────
vllm_cudnn_workaround() {
    freenemo_log "cuDNN graph corruption workaround (vLLM >= 0.23.0):"
    freenemo_log "  - Periodic graph revalidation enabled by default"
    freenemo_log "  - For Blackwell (B200/B300), add --no-enable-flashinfer-autotune if auto-tuning fails"
    freenemo_log "  - Alternative: --moe-backend triton to bypass FlashInfer MoE kernel bugs"
}

# ─── DEPLOYMENT MATRIX ──────────────────────────────────────────────────────
vllm_print_matrix() {
    cat <<'EOF'
════════════════════════════════════════════════════════════════════════════
                    vLLM DEPLOYMENT MATRIX — Nemotron 3 Ultra
════════════════════════════════════════════════════════════════════════════
Format      | Min Hardware          | VRAM    | Advantage
──────────────────────────────────────────────────────────────────────────────
BF16        | 16x H100 or 8x B200   | ~1265GB | Max accuracy, fine-tuning
FP8 (W8A8)  | 8x H100 or 4x B200    | ~660GB  | Balanced for Hopper
NVFP4 (W4A4)| 8x H100 or 4x B200/GB | ~352GB  | MAX throughput, 1.5-2.2x GEMM FLOPS on Blackwell
════════════════════════════════════════════════════════════════════════════
Required Flags:
  --quantization nvfp4              # Native 4-bit E2M1 weights
  --tensor-parallel-size 8          # Shard 512 experts across 8 GPUs via NVLink 4.0
  --kv-cache-dtype fp8              # 8-bit KV cache for GQA anchors (NOT nvfp4)
  --mamba-backend flashinfer        # Optimized CUDA kernels for Mamba-2 SSM
  --mamba-cache-dtype float16       # FP16 recurrent state (dynamic range)
  --enable-mamba-cache-stochastic-rounding   # Prevent state drift at 1M tokens
  --mamba-cache-philox-rounds 5     # 5 randomization rounds per state update
  --speculative-config.method mtp   # Native Multi-Token Prediction
  --speculative-config.num-speculative-tokens 5  # Draft 5 tokens/step
  --reasoning-parser nemotron_v3    # Dual-stream parser (reasoning + content)
  --tool-call-parser qwen3_coder    # NVIDIA-mandated tool calling format
  --disable-log-requests            # Prevent asyncio blocking from sync I/O
════════════════════════════════════════════════════════════════════════════
EOF
}
# ═══ MODULE: 08a_logging_session_core.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 08A: Logging & Session Structure — Core Logging Functions
# CSMLogs/Sessions/Session'Date-Time'/ — Heartbeat, gitstats, errors, performance
# ════════════════════════════════════════════════════════════════════════════

# ─── SESSION LOG STRUCTURE ──────────────────────────────────────────────────
# CSMLogs/
#   Sessions/
#     Session_YYYYMMDD-HHMMSS/
#       freenemo.log           # Main orchestrator log
#       heartbeats/
#         chamber_1.log        # Schumann chamber
#         chamber_2.log        # Geomag chamber
#         chamber_3.log        # Solar chamber
#         chamber_4.log        # Integration chamber
#         director_heartbeat.log  # Main heartbeat daemon
#       gitstats/
#         push_success.log     # Successful pushes
#         push_failure.log     # Failed pushes
#         pull_success.log     # Successful pulls
#         pull_failure.log     # Failed pulls
#         commit_count.log     # Commits per session
#       errors/
#         api_errors.log       # Nemotron API errors
#         transport_errors.log # Network/curl errors
#         git_errors.log       # Git operation errors
#         parse_errors.log     # JSON/stream parse errors
#       performance/
#         latency.log          # Request/response latency
#         token_usage.log      # Input/output tokens per request
#         throughput.log       # Tokens/second
#         timeout_count.log    # --max-time hits

LOG_INIT_DONE=false

log_init_session_dirs() {
    [[ "$LOG_INIT_DONE" == "true" ]] && return 0
    mkdir -p "${HEARTBEAT_LOG_DIR}" "${GIT_STATS_LOG_DIR}" "${ERROR_LOG_DIR}" "${PERF_LOG_DIR}"
    LOG_INIT_DONE=true
    freenemo_log "Session log directories initialized at ${SESSION_LOG_DIR}"
}

# ─── HEARTBEAT LOGGING ──────────────────────────────────────────────────────
log_heartbeat() {
    local chamber="$1" status="$2" detail="$3"
    log_init_session_dirs
    local log_file="${HEARTBEAT_LOG_DIR}/chamber_${chamber}.log"
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ${chamber} | ${status} | ${detail}" >> "${log_file}"
}

log_director_heartbeat() {
    log_init_session_dirs
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | DIRECTOR | $1" >> "${HEARTBEAT_LOG_DIR}/director_heartbeat.log"
}

# ─── GIT STATS LOGGING ──────────────────────────────────────────────────────
log_git_push() {
    local status="$1" branch="$2" detail="$3"
    log_init_session_dirs
    local log_file="${GIT_STATS_LOG_DIR}/push_${status}.log"
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | branch=${branch} | ${detail}" >> "${log_file}"
    if [[ "$status" == "success" ]]; then
        local count_file="${GIT_STATS_LOG_DIR}/commit_count.log"
        local count=$(cat "${count_file}" 2>/dev/null || echo 0)
        echo $((count + 1)) > "${count_file}"
    fi
}

log_git_pull() {
    local status="$1" detail="$2"
    log_init_session_dirs
    local log_file="${GIT_STATS_LOG_DIR}/pull_${status}.log"
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ${detail}" >> "${log_file}"
}

# ─── ERROR LOGGING ──────────────────────────────────────────────────────────
log_error() {
    local category="$1" message="$2" context="${3:-}"
    log_init_session_dirs
    local log_file="${ERROR_LOG_DIR}/${category}_errors.log"
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ${message} | ${context}" >> "${log_file}"
    freenemo_error "[${category}] ${message}"
}

# ─── PERFORMANCE LOGGING ────────────────────────────────────────────────────
log_perf_latency() {
    local endpoint="$1" latency_ms="$2" status="$3"
    log_init_session_dirs
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ${endpoint} | ${latency_ms}ms | ${status}" >> "${PERF_LOG_DIR}/latency.log"
}

log_perf_tokens() {
    local input_tokens="$1" output_tokens="$2" reasoning_tokens="$3"
    log_init_session_dirs
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | in=${input_tokens} out=${output_tokens} reasoning=${reasoning_tokens}" >> "${PERF_LOG_DIR}/token_usage.log"
}

log_perf_throughput() {
    local tokens="$1" duration_ms="$2"
    local tps=$(awk "BEGIN{printf \"%.2f\", $tokens/($duration_ms/1000)}")
    log_init_session_dirs
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ${tokens} tokens in ${duration_ms}ms = ${tps} tok/s" >> "${PERF_LOG_DIR}/throughput.log"
}

log_timeout() {
    local operation="$1" timeout_sec="$2"
    log_init_session_dirs
    echo "$(date -u +%Y-%m-%dT%H:%M:%SZ) | ${operation} | timeout=${timeout_sec}s" >> "${PERF_LOG_DIR}/timeout_count.log"
    freenemo_warn "TIMEOUT: ${operation} exceeded ${timeout_sec}s"
}
# ═══ MODULE: 08b_logging_session_printer.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 08B: Logging & Session Structure — Periodic Printer & Session Summary
# Terminal printing every N seconds, session summary on exit
# ════════════════════════════════════════════════════════════════════════════

# ─── PERIODIC TERMINAL PRINTING ─────────────────────────────────────────────
# Runs in background, prints summary every N seconds
log_periodic_printer() {
    local interval="${1:-30}"
    log_init_session_dirs
    freenemo_log "Starting periodic terminal printer (every ${interval}s)"

    while true; do
        sleep "${interval}"
        echo "" >&2
        freenemo_banner "📊 PERIODIC STATUS — $(date -u +%H:%M:%S)"
        
        # Heartbeat summary
        if [[ -f "${HEARTBEAT_LOG_DIR}/director_heartbeat.log" ]]; then
            local last_hb=$(tail -1 "${HEARTBEAT_LOG_DIR}/director_heartbeat.log" 2>/dev/null)
            freenemo_log "Last Director HB: ${last_hb}"
        fi

        # Git stats
        local pushes_ok=$(wc -l < "${GIT_STATS_LOG_DIR}/push_success.log" 2>/dev/null || echo 0)
        local pushes_fail=$(wc -l < "${GIT_STATS_LOG_DIR}/push_failure.log" 2>/dev/null || echo 0)
        local pulls_ok=$(wc -l < "${GIT_STATS_LOG_DIR}/pull_success.log" 2>/dev/null || echo 0)
        local pulls_fail=$(wc -l < "${GIT_STATS_LOG_DIR}/pull_failure.log" 2>/dev/null || echo 0)
        local commits=$(cat "${GIT_STATS_LOG_DIR}/commit_count.log" 2>/dev/null || echo 0)
        freenemo_log "Git: ${pushes_ok}✓/${pushes_fail}✗ pushes, ${pulls_ok}✓/${pulls_fail}✗ pulls, ${commits} commits"

        # Errors
        local api_err=$(wc -l < "${ERROR_LOG_DIR}/api_errors.log" 2>/dev/null || echo 0)
        local net_err=$(wc -l < "${ERROR_LOG_DIR}/transport_errors.log" 2>/dev/null || echo 0)
        local git_err=$(wc -l < "${ERROR_LOG_DIR}/git_errors.log" 2>/dev/null || echo 0)
        local parse_err=$(wc -l < "${ERROR_LOG_DIR}/parse_errors.log" 2>/dev/null || echo 0)
        freenemo_log "Errors: API=${api_err} Net=${net_err} Git=${git_err} Parse=${parse_err}"

        # Performance
        local timeouts=$(wc -l < "${PERF_LOG_DIR}/timeout_count.log" 2>/dev/null || echo 0)
        local avg_tps=$(awk '{sum+=$NF} END{if(NR>0) printf "%.1f", sum/NR; else print "0"}' "${PERF_LOG_DIR}/throughput.log" 2>/dev/null || echo 0)
        freenemo_log "Perf: ${timeouts} timeouts, avg ${avg_tps} tok/s"

        # Earthbeat chamber status
        for c in 1 2 3 4; do
            local log="${HEARTBEAT_LOG_DIR}/chamber_${c}.log"
            [[ -f "$log" ]] && local last=$(tail -1 "$log" 2>/dev/null) && freenemo_log "Chamber $c: ${last}" || true
        done
    done
}

# ─── SESSION SUMMARY (on exit) ──────────────────────────────────────────────
log_session_summary() {
    freenemo_banner "📋 SESSION SUMMARY — $(date -u +%Y-%m-%dT%H:%M:%SZ)"
    local duration=$(($(date -u +%s) - FREENEMO_START_TIME))
    freenemo_log "Session duration: ${duration}s"
    freenemo_log "Log directory: ${SESSION_LOG_DIR}"

    [[ -f "${GIT_STATS_LOG_DIR}/commit_count.log" ]] && freenemo_log "Total commits: $(cat "${GIT_STATS_LOG_DIR}/commit_count.log")"
    [[ -f "${PERF_LOG_DIR}/timeout_count.log" ]] && freenemo_log "Total timeouts: $(wc -l < "${PERF_LOG_DIR}/timeout_count.log")"
    [[ -f "${ERROR_LOG_DIR}/api_errors.log" ]] && freenemo_log "Total API errors: $(wc -l < "${ERROR_LOG_DIR}/api_errors.log")"
}
# ═══ MODULE: 09a_error_recovery_repo.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 09A: Error Recovery — Repo Load Failure & Git Conflict Resolution
# Handles: network failures, git conflicts, repo cloning strategies
# ════════════════════════════════════════════════════════════════════════════

# ─── REPO LOAD RECOVERY ─────────────────────────────────────────────────────
# If repo cannot be loaded at launch, try multiple strategies
repo_recover_load() {
    freenemo_banner "🔧 REPO RECOVERY — Attempting to Load Repository"

    # Strategy 1: Standard discovery
    if freenemo_git_discover_repo; then
        freenemo_success "Repo discovered at: ${REPO_ROOT}"
        return 0
    fi

    # Strategy 2: Clone from known URL
    freenemo_warn "Strategy 1 failed. Trying clone from ${REPO_URL}..."
    local clone_dir="/tmp/freenemo-repo-$(date +%s)"
    if git clone "${REPO_URL}" "${clone_dir}" 2>/dev/null; then
        REPO_ROOT="${clone_dir}"
        export REPO_ROOT
        freenemo_success "Cloned repo to: ${REPO_ROOT}"
        return 0
    fi

    # Strategy 3: Shallow clone (faster, less bandwidth)
    freenemo_warn "Full clone failed. Trying shallow clone..."
    if git clone --depth 1 "${REPO_URL}" "${clone_dir}" 2>/dev/null; then
        REPO_ROOT="${clone_dir}"
        export REPO_ROOT
        freenemo_success "Shallow cloned repo to: ${REPO_ROOT}"
        return 0
    fi

    # Strategy 4: Try alternative remote (SSH vs HTTPS)
    freenemo_warn "HTTPS clone failed. Trying SSH..."
    local ssh_url="${REPO_URL/https:\/\/github.com\//git@github.com:}"
    if git clone "${ssh_url}" "${clone_dir}" 2>/dev/null; then
        REPO_ROOT="${clone_dir}"
        export REPO_ROOT
        freenemo_success "SSH cloned repo to: ${REPO_ROOT}"
        return 0
    fi

    freenemo_error "All repo recovery strategies failed"
    return 1
}

# ─── GIT CONFLICT RESOLUTION ────────────────────────────────────────────────
git_resolve_conflicts() {
    freenemo_log "Checking for git conflicts..."
    if git status --short | grep -q "^UU\|^AA\|^DD"; then
        freenemo_warn "Conflicts detected. Attempting auto-resolution..."
        # Try ours strategy for binary/config files
        git diff --name-only --diff-filter=U | while read -r file; do
            if [[ "$file" == *.md || "$file" == *.txt || "$file" == *.json || "$file" == *.yaml || "$file" == *.yml ]]; then
                freenemo_log "Auto-merging text file: $file"
                git checkout --ours -- "$file" 2>/dev/null || true
                git add "$file"
            fi
        done
        # Commit resolved
        if ! git diff --cached --quiet; then
            git commit -m "[AUTO-RESOLVE] Merge conflict resolution" >/dev/null 2>&1 || true
            freenemo_success "Conflicts auto-resolved and committed"
        fi
    else
        freenemo_log "No conflicts detected"
    fi
}
# ═══ MODULE: 09b_error_recovery_api.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 09B: Error Recovery — API Error Recovery & Parser Recovery
# Handles: empty content (finish_reason=length), tool call dropping, socket stalls, SSE parsing
# ════════════════════════════════════════════════════════════════════════════

# ─── API ERROR RECOVERY ─────────────────────────────────────────────────────
# Handles: empty content (finish_reason=length), tool call dropping, socket stalls
api_recover_empty_content() {
    local response="$1"
    local finish_reason=$(echo "$response" | jq -r '.choices[0].finish_reason // empty')
    local content=$(echo "$response" | jq -r '.choices[0].message.content // empty')
    local reasoning=$(echo "$response" | jq -r '.choices[0].message.reasoning_content // empty')

    if [[ -z "$content" && "$finish_reason" == "length" ]]; then
        freenemo_warn "Empty content with finish_reason=length — token budget exhausted in reasoning"
        freenemo_log "Recovery: Increase max_tokens or decrease thinking_token_budget"
        # Return reasoning as fallback content
        if [[ -n "$reasoning" ]]; then
            echo "$reasoning"
            return 0
        fi
        return 1
    fi

    if [[ -z "$content" && -n "$reasoning" ]]; then
        freenemo_warn "Content empty but reasoning present — possible tool call drop (force_nonempty_content needed)"
        # Try to extract tool calls from reasoning
        echo "$reasoning" | grep -o '{"name".*}' | head -1 || echo "$reasoning"
        return 0
    fi

    echo "$content"
    return 0
}

api_recover_transport() {
    local attempt=1 max_attempts=3 delay=2
    while true; do
        if "$@"; then return 0; fi
        local exit_code=$?
        if [[ $attempt -ge $max_attempts ]]; then
            log_error "transport" "Command failed after $max_attempts attempts" "$*"
            return $exit_code
        fi
        freenemo_warn "Transport error (attempt $attempt/$max_attempts). Retrying in ${delay}s..."
        sleep "$delay"
        delay=$((delay * 2))
        attempt=$((attempt + 1))
    done
}

# ─── PARSER RECOVERY ────────────────────────────────────────────────────────
parse_recover_sse() {
    local line="$1"
    local clean="${line#data: }"
    [[ -z "$clean" || "$clean" == "[DONE]" ]] && return 1

    # Try multiple field paths for reasoning
    local reasoning=$(echo "$clean" | jq -r '.choices[0].delta.reasoning_content // .choices[0].delta.reasoning // empty' 2>/dev/null || true)
    # Try multiple field paths for content
    local content=$(echo "$clean" | jq -r '.choices[0].delta.content // empty' 2>/dev/null || true)

    # If both empty, log parse error
    if [[ -z "$reasoning" && -z "$content" ]]; then
        log_error "parse" "SSE parse returned empty for both reasoning and content" "line: $line"
        return 1
    fi

    # Output what we found
    [[ -n "$reasoning" ]] && printf "\e[2;37m%s\e[0m" "$reasoning"
    [[ -n "$content" ]] && printf "\e[1;32m%s\e[0m" "$content"
    return 0
}
# ═══ MODULE: 09c_error_recovery_health.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 09C: Error Recovery — Heartbeat/Chamber Recovery & Health Check
# Handles: daemon restarts, chamber restarts, comprehensive health verification
# ════════════════════════════════════════════════════════════════════════════

# ─── HEARTBEAT RECOVERY ─────────────────────────────────────────────────────
heartbeat_recover_daemon() {
    if ! kill -0 "${HEARTBEAT_PID:-0}" 2>/dev/null; then
        freenemo_warn "Heartbeat daemon died (PID: ${HEARTBEAT_PID:-unknown}). Restarting..."
        local hb_script="${REPO_ROOT}/CSMScripts/heartbeat-daemon.sh"
        if [[ -f "$hb_script" ]]; then
            bash "$hb_script" &
            HEARTBEAT_PID=$!
            export HEARTBEAT_PID
            freenemo_success "Heartbeat daemon restarted (PID: $HEARTBEAT_PID)"
        fi
    fi
}

# ─── EARTHBEAT CHAMBER RECOVERY ─────────────────────────────────────────────
earthbeat_recover_chamber() {
    local chamber="$1"
    local pid_file="${REPO_ROOT}/CSMScripts/earthbeatv3-chamber-${chamber}.pid"
    local pid=$(cat "$pid_file" 2>/dev/null || echo 0)
    if ! kill -0 "$pid" 2>/dev/null; then
        freenemo_warn "Chamber $chamber died (PID: $pid). Restarting..."
        # Restart logic would call the chamber function
        return 1
    fi
    return 0
}

# ─── COMPREHENSIVE HEALTH CHECK ─────────────────────────────────────────────
health_check_all() {
    freenemo_banner "🏥 COMPREHENSIVE HEALTH CHECK"

    local issues=0

    # Repo
    if ! git -C "${REPO_ROOT}" rev-parse --is-inside-work-tree >/dev/null 2>&1; then
        freenemo_error "Repo not accessible"
        ((issues++))
    else
        freenemo_success "Repo OK"
    fi

    # Git sync
    if git -C "${REPO_ROOT}" ls-remote --heads origin main >/dev/null 2>&1; then
        freenemo_success "Git remote reachable"
    else
        freenemo_warn "Git remote unreachable"
        ((issues++))
    fi

    # Heartbeat daemon
    heartbeat_recover_daemon

    # Earthbeat chambers
    for c in 1 2 3 4; do
        earthbeat_recover_chamber "$c" || ((issues++))
    done

    # API endpoint
    if transport_check_connectivity "${NEMOTRON_API_ENDPOINT}"; then
        freenemo_success "API endpoint reachable"
    else
        freenemo_error "API endpoint unreachable"
        ((issues++))
    fi

    # Disk space
    local disk_avail=$(df -h "${REPO_ROOT}" | awk 'NR==2 {print $4}')
    freenemo_log "Disk available: ${disk_avail}"

    if [[ $issues -eq 0 ]]; then
        freenemo_success "All systems healthy"
        return 0
    else
        freenemo_warn "$issues issue(s) detected"
        return 1
    fi
}
# ═══ MODULE: 10a_main_orchestrator_setup.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 10A: Main Orchestrator — Setup, Preflight, Session Init, Earthbeat Launch
# Global state, signal handling, mode parsing, preflight checks
# ════════════════════════════════════════════════════════════════════════════

# ─── GLOBAL STATE ────────────────────────────────────────────────────────────
ORCH_PIDS=()
ORCH_CHAMBER_PIDS=()
ORCH_RUNNING=true
ORCH_ITERATION=0

# ─── SIGNAL HANDLING ─────────────────────────────────────────────────────────
orch_cleanup() {
    freenemo_log "Shutting down orchestrator..."
    ORCH_RUNNING=false
    for pid in "${ORCH_PIDS[@]}" "${ORCH_CHAMBER_PIDS[@]}"; do
        kill "$pid" 2>/dev/null || true
    done
    wait 2>/dev/null || true
    log_session_summary
    freenemo_success "Orchestrator stopped cleanly"
    exit 0
}
trap orch_cleanup SIGTERM SIGINT EXIT

# ─── MODE PARSING ────────────────────────────────────────────────────────────
orch_parse_mode() {
    MODE="chamber"
    COUNT=4
    TOKENRING=false
    PARALLEL=false
    REPEAT=1  # Number of times to reiterate the full procedure

    if [[ $# -gt 0 ]]; then
        case "$1" in
            chamber) MODE="chamber" ;;
            parallel) PARALLEL=true; MODE="parallel"; [[ $# -ge 2 && "$2" =~ ^[0-9]+$ ]] && COUNT=$2; shift ;;
            tokenring) TOKENRING=true; MODE="tokenring"; [[ $# -ge 2 && "$2" =~ ^[0-9]+$ ]] && COUNT=$2; shift ;;
            repeat) REPEAT="${2:-1}"; shift ;;
            *) [[ "$1" =~ ^[0-9]+$ ]] && COUNT=$1 ;;
        esac
        [[ "$1" == "parallel" && "$2" == "tokenring" ]] && { TOKENRING=true; MODE="tokenring"; [[ $# -ge 3 && "$3" =~ ^[0-9]+$ ]] && COUNT=$3; }
    fi
}

# ─── PRE-FLIGHT CHECKS ───────────────────────────────────────────────────────
orch_preflight() {
    freenemo_banner "🚀 FREENEMO PRE-FLIGHT CHECKS"

    # Transport hardening
    transport_setup_ssh_multiplexing
    transport_tune_kernel

    # vLLM config check
    vllm_check_hardware
    vllm_print_matrix

    # Health check
    health_check_all || freenemo_warn "Health check issues detected, continuing anyway..."

    # Start periodic logger
    log_periodic_printer 30 &
    ORCH_PIDS+=($!)
    freenemo_log "Periodic logger started (PID: $!)"

    freenemo_success "Pre-flight complete"
}

# ─── SESSION INITIALIZATION ──────────────────────────────────────────────────
orch_session_init() {
    freenemo_banner "📋 SESSION INITIALIZATION"
    session_init_main
    freenemo_success "Session initialized"
}

# ─── EARTHBEAT LAUNCHER ──────────────────────────────────────────────────────
orch_launch_earthbeat() {
    freenemo_banner "🌍 LAUNCHING EARTHBEAT — Mode: $MODE"

    case "$MODE" in
        chamber)
            eb_run_chamber_mode &
            ORCH_CHAMBER_PIDS+=($!)
            ;;
        parallel|tokenring)
            eb_run_parallel "$MODE" "$COUNT" &
            ORCH_CHAMBER_PIDS+=($!)
            ;;
    esac

    freenemo_log "Earthbeat launched (PIDs: ${ORCH_CHAMBER_PIDS[*]})"
}
# ═══ MODULE: 10b_main_orchestrator_loop.sh ═══════════════════════════════════════════════════
#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════════════
# MODULE 10B: Main Orchestrator — Nemotron Loop, GitHub Sync, Main Entry
# API loop, periodic GitHub sync, procedure reiteration
# ════════════════════════════════════════════════════════════════════════════

# ─── NEMOTRON API LOOP ───────────────────────────────────────────────────────
orch_nemotron_loop() {
    freenemo_banner "🤖 NEMOTRON 3 ULTRA API LOOP — Starting"

    local iteration=0
    while $ORCH_RUNNING; do
        iteration=$((iteration + 1))
        ORCH_ITERATION=$iteration
        freenemo_log "=== Nemotron Loop Iteration $iteration ==="

        # Example: Run a quick nemotron command
        local prompt="System health check: Report current git status, disk usage, and any errors in ${ERROR_LOG_DIR}. Output as JSON."
        local payload=$(nemotron_build_payload "$prompt" false "low" 256 1024 true '{"type": "json_object"}' true)
        
        freenemo_log "Sending request to Nemotron..."
        local start_ms=$(date +%s%3N)
        nemotron_stream_reader "$payload" 60
        local end_ms=$(date +%s%3N)
        local latency=$((end_ms - start_ms))
        
        log_perf_latency "nemotron_api" "$latency" "success"
        log_perf_throughput 0 "$latency"

        # Sleep between iterations (adjustable)
        sleep 10
    done
}

# ─── GITHUB HANDLER INTEGRATION ──────────────────────────────────────────────
orch_github_sync() {
    freenemo_log "Syncing session logs to GitHub..."
    
    # Save main log
    gh_save_file "${SESSION_LOG_DIR}/freenemo.log" "Session log: $(date -u)" "$BRANCH_NAME"
    log_git_push "success" "$BRANCH_NAME" "freenemo.log"

    # Save heartbeat logs
    for hb_log in "${HEARTBEAT_LOG_DIR}"/*.log; do
        [[ -f "$hb_log" ]] || continue
        gh_save_file "$hb_log" "Heartbeat: $(basename "$hb_log")" "$BRANCH_NAME"
        log_git_push "success" "$BRANCH_NAME" "$(basename "$hb_log")"
    done

    # Save git stats
    for gs_log in "${GIT_STATS_LOG_DIR}"/*.log; do
        [[ -f "$gs_log" ]] || continue
        gh_save_file "$gs_log" "GitStats: $(basename "$gs_log")" "$BRANCH_NAME"
    done

    # Save errors
    for err_log in "${ERROR_LOG_DIR}"/*.log; do
        [[ -f "$err_log" ]] || continue
        gh_save_file "$err_log" "Errors: $(basename "$err_log")" "$BRANCH_NAME"
    done

    # Save performance
    for perf_log in "${PERF_LOG_DIR}"/*.log; do
        [[ -f "$perf_log" ]] || continue
        gh_save_file "$perf_log" "Perf: $(basename "$perf_log")" "$BRANCH_NAME"
    done

    freenemo_success "GitHub sync complete"
}

# ─── MAIN ORCHESTRATOR ENTRY ─────────────────────────────────────────────────
freenemo_main() {
    orch_parse_mode "$@"
    
    freenemo_banner "═══════════════════════════════════════════════════════════════"
    freenemo_banner "  FREENEMO v${FREENEMO_VERSION} — Nemotron 3 Ultra Orchestrator"
    freenemo_banner "  Mode: $MODE | Count: $COUNT | Repeat: $REPEAT"
    freenemo_banner "  Session: ${FREENEMO_SESSION_ID} | Agent: ${FREENEMO_AGENT_ID}"
    freenemo_banner "═══════════════════════════════════════════════════════════════"

    # Run the full procedure REPEAT times
    for ((rep=1; rep<=REPEAT; rep++)); do
        freenemo_banner "🔄 PROCEDURE ITERATION $rep / $REPEAT"
        
        # Recovery check at start of each iteration
        repo_recover_load || { freenemo_error "Repo recovery failed"; return 1; }
        
        orch_preflight
        orch_session_init
        orch_launch_earthbeat
        
        # Run nemotron loop in background
        orch_nemotron_loop &
        ORCH_PIDS+=($!)
        
        # GitHub sync loop (every 5 minutes)
        (
            while $ORCH_RUNNING; do
                sleep 300
                orch_github_sync
            done
        ) &
        ORCH_PIDS+=($!)
        
        # Wait for all background processes
        wait
        
        # If not last iteration, brief pause before restart
        if (( rep < REPEAT )); then
            freenemo_log "Iteration $rep complete. Pausing 5s before next iteration..."
            sleep 5
        fi
    done
    
    freenemo_success "All $REPEAT iterations complete"
}
